                }
                let brokenBarOffset: Double = self.smuflMetrics.brokenBeamWidth * scaleMod
                let barCount: Double = try ModelUtils.getIndex(beat.duration) - 2.0
                let barStart: Double = cy + self.y
                let stemThickness: Double = self.smuflMetrics.stemThickness
                do {
                    var barIndex: Double = 0.0
                    while barIndex < barCount {
                        var barStartX: Double = Math.floor(stemX + stemThickness)
                        var barEndX: Double = 0.0
                        var barStartY: Double = 0.0
                        var barEndY: Double = 0.0
                        let barY: Double = barStart + barIndex * barSpacing
                        if i < h.beats.length - 1.0 {
                            let isFullBarJoin: Bool = try BeamingHelper.isFullBarJoin(beat, h.beats[(i + 1.0).toInt()], barIndex)
                            if barIndex == barCount - 1.0 && isFullBarJoin && beat.beamingMode == BeatBeamingMode.ForceSplitOnSecondaryToNext {
                                barEndX = Math.ceil(barStartX + brokenBarOffset)
                                try barStartY = barY + self.calculateBeamY(h, barStartX)
                                try barEndY = barY + self.calculateBeamY(h, barEndX)
                                LineBarRenderer.paintSingleBar(canvas, cx + self.x + barStartX, barStartY, cx + self.x + barEndX, barEndY, barSize)
                                barEndX = Math.floor(self.getBeatX(h.beats[(i + 1.0).toInt()], BeatXPosition.Stem))
                                barStartX = Math.floor(barEndX - brokenBarOffset)
                                try barStartY = barY + self.calculateBeamY(h, barStartX)
                                try barEndY = barY + self.calculateBeamY(h, barEndX)
                                LineBarRenderer.paintSingleBar(canvas, cx + self.x + barStartX, barStartY, cx + self.x + barEndX, barEndY, barSize)
                            } else {
                                if isFullBarJoin {
                                    barEndX = Math.ceil(self.getBeatX(h.beats[(i + 1.0).toInt()], BeatXPosition.Stem))
                                } else if try i == 0.0 || !BeamingHelper.isFullBarJoin(h.beats[(i - 1.0).toInt()], beat, barIndex) {
                                    barEndX = Math.ceil(barStartX + brokenBarOffset)
                                } else {
                                    barIndex += 1
                                    continue
                                }
                                try barStartY = barY + self.calculateBeamY(h, barStartX)
                                try barEndY = barY + self.calculateBeamY(h, barEndX)
                                LineBarRenderer.paintSingleBar(canvas, cx + self.x + barStartX, barStartY, cx + self.x + barEndX, barEndY, barSize)
                            }
                        } else if try i > 0 && !BeamingHelper.isFullBarJoin(beat, h.beats[(i - 1.0).toInt()], barIndex) {
                            barEndX = Math.ceil(stemX)
                            barStartX = Math.floor(stemX - brokenBarOffset)
                            try barStartY = barY + self.calculateBeamY(h, barStartX)
                            try barEndY = barY + self.calculateBeamY(h, barEndX)
                            LineBarRenderer.paintSingleBar(canvas, cx + self.x + barStartX, barStartY, cx + self.x + barEndX, barEndY, barSize)
                        }
                        barIndex += 1
                    }
                }
                i += 1
            }
        }
        if h.graceType == GraceType.BeforeBeat {
            let beatLineX: Double = self.getBeatX(h.beats[0], BeatXPosition.Stem)
            let flagWidth: Double = try jsNonNull(self.smuflMetrics.glyphWidths.get(MusicFontSymbol.Flag8thUp)) * EngravingSettings.GraceScale
            var slashY: Double = try try jsOr(cy + self.y + self.calculateBeamY(h, beatLineX), 0)
            slashY += barSize + barSpacing
            if direction == BeamDirection.Down {
                try CanvasHelper.fillMusicFontSymbolSafe(canvas, cx + self.x + beatLineX + flagWidth / 2.0, slashY, EngravingSettings.GraceScale, MusicFontSymbol.GraceNoteSlashStemDown, true)
            } else {
                try CanvasHelper.fillMusicFontSymbolSafe(canvas, cx + self.x + beatLineX + flagWidth / 2.0, slashY, EngravingSettings.GraceScale, MusicFontSymbol.GraceNoteSlashStemUp, true)
            }
        }
    }

    internal static func paintSingleBar(_ canvas: any ICanvas, _ x1: Double, _ y1: Double, _ x2: Double, _ y2: Double, _ size: Double) {
        canvas.beginPath()
        canvas.moveTo(x1, y1)
        canvas.lineTo(x2, y2)
        canvas.lineTo(x2, y2 + size)
        canvas.lineTo(x1, y1 + size)
        canvas.closePath()
        canvas.fill()
    }

    /**
     * Writes the helper's beam/flag/tuplet-bracket y-extent into `out` (0 = no overflow on that side).
     */
    private func _computeBeamingBounds(_ h: BeamingHelper, _ out: BeamingBounds) throws {
        var topY: Double = 0.0
        var bottomY: Double = 0.0
        if try !self.shouldPaintBeamingHelper(h) {
            if h.hasTuplet && h.isRestBeamHelper {
                let tupletGroup: TupletGroup = try jsNonNull(h.beats.jsElement(0).tupletGroup)
                let tupletFirst: Beat = tupletGroup.beats[0]
                let tupletLast: Beat = tupletGroup.beats[(tupletGroup.beats.length - 1.0).toInt()]
                let tupletDirection: BeamDirection = try self.getTupletBeamDirection(h)
                if tupletDirection == BeamDirection.Up {
                    let restTop: Double = try Math.min(self.getRestY(tupletFirst, NoteYPosition.Top), self.getRestY(tupletLast, NoteYPosition.Top))
                    topY = restTop - self.tupletSize - self.tupletOffset
                } else {
                    let restBottom: Double = try Math.max(self.getRestY(tupletFirst, NoteYPosition.Bottom), self.getRestY(tupletLast, NoteYPosition.Bottom))
                    bottomY = restBottom + self.tupletSize + self.tupletOffset
                }
            }
        } else if try h.beats.length == 1.0 && h.beats.jsElement(0).duration >= Duration.Half {
            let tupletDirection: BeamDirection = try self.getTupletBeamDirection(h)
            let direction: BeamDirection = try self.getBeamDirection(h)
            let flagOverflow: Double = try jsNonNull(self.smuflMetrics.stemFlagOffsets.get(h.beats.jsElement(0).duration))
            if direction == BeamDirection.Up {
                try topY = self.getFlagTopY(h.beats[0], direction) - flagOverflow
                if h.hasTuplet && tupletDirection == (direction as! BeamDirection) {
                    topY -= self.tupletSize + self.tupletOffset
                }
                if h.hasTuplet && tupletDirection != (direction as! BeamDirection) {
                    try bottomY = self.getFlagBottomY(h.beats[0], tupletDirection)
                    bottomY += self.tupletSize + self.tupletOffset
                }
            } else {
                try bottomY = self.getFlagBottomY(h.beats[0], direction) + flagOverflow
                if h.hasTuplet && tupletDirection == (direction as! BeamDirection) {
                    bottomY += self.tupletSize + self.tupletOffset
                }
                if h.hasTuplet && tupletDirection != (direction as! BeamDirection) {
                    try topY = self.getFlagTopY(h.beats[0], tupletDirection)
                    topY -= self.tupletSize + self.tupletOffset
                }
            }
        } else {
            let direction: BeamDirection = try self.getBeamDirection(h)
            try self.ensureBeamDrawingInfo(h, direction)
            let drawingInfo: BeamingHelperDrawInfo = h.getDrawingInfo(direction)
            let tupletDirection: BeamDirection = try self.getTupletBeamDirection(h)
            if direction == BeamDirection.Up {
                topY = Math.min(drawingInfo.startY, drawingInfo.endY)
                if h.hasTuplet && tupletDirection == (direction as! BeamDirection) {
                    topY -= self.tupletSize + self.tupletOffset
                }
                if h.hasTuplet && tupletDirection != (direction as! BeamDirection) {
                    try bottomY = self.getFlagBottomY(h.beatOfLowestNote, tupletDirection) + self.tupletSize + self.tupletOffset
                } else {
                    try bottomY = self.voiceContainer.getLowestNoteY(h.beatOfLowestNote, NoteYPosition.Bottom)
                }
            } else {
                bottomY = Math.max(drawingInfo.startY, drawingInfo.endY)
                if h.hasTuplet && tupletDirection == (direction as! BeamDirection) {
                    bottomY += self.tupletSize + self.tupletOffset
                }
                if h.hasTuplet && tupletDirection != (direction as! BeamDirection) {
                    try topY = self.getFlagTopY(h.beatOfHighestNote, tupletDirection) - self.tupletSize - self.tupletOffset
                } else {
                    try topY = self.voiceContainer.getHighestNoteY(h.beatOfHighestNote, NoteYPosition.Top)
                }
            }
        }
        out.topY = topY
        out.bottomY = bottomY
    }

    private var _beamingBoundsScratch: BeamingBounds = BeamingBounds(topY: 0.0, bottomY: 0.0)

    internal func calculateBeamingOverflows(_ rendererTop: Double, _ rendererBottom: Double) throws {
        let out: BeamingBounds = self._beamingBoundsScratch
        for v in self.helpers.beamHelpers {
            for h in v {
                try self._computeBeamingBounds(h, out)
                if out.topY < rendererTop {
                    self.registerOverflowTop(Math.abs(out.topY))
                }
                if out.bottomY > rendererBottom {
                    self.registerOverflowBottom(Math.abs(out.bottomY) - rendererBottom)
                }
            }
        }
    }

    internal override func emitHelperSkyline(_ h: BeamingHelper) throws {
        let rendererBottom: Double = self.height
        let out: BeamingBounds = self._beamingBoundsScratch
        try self._computeBeamingBounds(h, out)
        if out.topY >= 0 && out.bottomY <= rendererBottom {
            return
        }
        let firstBeat: Beat = h.beats[0]
        let lastBeat: Beat = h.beats[(h.beats.length - 1.0).toInt()]
        if try !self.shouldPaintBeamingHelper(h) || h.hasTuplet {
            let xStart: Double = self.getBeatX(firstBeat, BeatXPosition.PreNotes)
            let xEnd: Double = self.getBeatX(lastBeat, BeatXPosition.PostNotes)
            if out.topY < 0 {
                try self.insertSkylineTop(xStart, xEnd, -out.topY)
            }
            if out.bottomY > rendererBottom {
                try self.insertSkylineBottom(xStart, xEnd, out.bottomY - rendererBottom)
            }
            return
        }
        let direction: BeamDirection = try self.getBeamDirection(h)
        let stemStartX: Double = self.getBeatX(firstBeat, BeatXPosition.Stem)
        if h.beats.length == 1.0 {
            let flagOverflow: Double = try jsNonNull(self.smuflMetrics.stemFlagOffsets.get(firstBeat.duration))
            var xEnd: Double
            if flagOverflow != 0.0 {
                let symbol: MusicFontSymbol = FlagGlyph.getSymbol(firstBeat.duration, direction, firstBeat.graceType != GraceType.None)
                try xEnd = stemStartX + jsNonNull(self.smuflMetrics.glyphWidths.get(symbol))
            } else {
                xEnd = stemStartX + self.smuflMetrics.stemThickness
            }
            if out.topY < 0 {
                try self.insertSkylineTop(stemStartX, xEnd, -out.topY)
            }
            if out.bottomY > rendererBottom {
                try self.insertSkylineBottom(stemStartX, xEnd, out.bottomY - rendererBottom)
            }
            return
        }
        let stemEndX: Double = self.getBeatX(lastBeat, BeatXPosition.Stem) + self.smuflMetrics.stemThickness
        if direction == BeamDirection.Up {
            if out.topY < 0 {
                try self._emitSlopedBeamEdge(h, stemStartX, stemEndX, true, rendererBottom)
            }
            if out.bottomY > rendererBottom {
                try self._emitPerBeatNoteEdge(h, false, rendererBottom)
            }
        } else {
            if out.bottomY > rendererBottom {
                try self._emitSlopedBeamEdge(h, stemStartX, stemEndX, false, rendererBottom)
            }
            if out.topY < 0 {
                try self._emitPerBeatNoteEdge(h, true, rendererBottom)
            }
        }
    }

    /**
     * Registers the note side of a beamed group per beat: each notehead's own x-extent at
     * its own height, so an ascending/descending run registers as a matching contour rather
     * than one flat rectangle at the highest/lowest note across the whole group.
     */
    private func _emitPerBeatNoteEdge(_ h: BeamingHelper, _ isTop: Bool, _ rendererBottom: Double) throws {
        for beat in h.beats {
            let xL: Double = self.getBeatX(beat, BeatXPosition.OnNotes)
            let xR: Double = self.getBeatX(beat, BeatXPosition.PostNotes)
            if xR <= xL {
                continue
            }
            if isTop {
                let y: Double = try self.voiceContainer.getHighestNoteY(beat, NoteYPosition.Top)
                if y < 0 {
                    try self.insertSkylineTop(xL, xR, -y)
                }
            } else {
                let y: Double = try self.voiceContainer.getLowestNoteY(beat, NoteYPosition.Bottom)
                if y > rendererBottom {
                    try self.insertSkylineBottom(xL, xR, y - rendererBottom)
                }
            }
        }
    }

    /**
     * Registers the (linear) beam edge between `xStart` and `xEnd` as a stair-step that
     * follows its slope. Each step is raised to the outer (highest for top / lowest for
     * bottom) beam-y within that step, so the skyline never under-reaches the beam yet
     * doesn't claim the beam's peak height across its whole width. Step count scales with
     * the slope's total rise (flat beam → one segment).
     */
    private func _emitSlopedBeamEdge(_ h: BeamingHelper, _ xStart: Double, _ xEnd: Double, _ isTop: Bool, _ rendererBottom: Double) throws {
        let span: Double = xEnd - xStart
        if span <= 0 {
            return
        }
        let yStart: Double = try self.calculateBeamY(h, xStart)
        let yEnd: Double = try self.calculateBeamY(h, xEnd)
        let steps: Double = Math.max(1.0, Math.min(16.0, Math.ceil(Math.abs(yEnd - yStart) / 2.0)))
        do {
            var i: Double = 0.0
            while i < steps {
                let xa: Double = xStart + (span * i) / steps
                let xb: Double = xStart + (span * (i + 1.0)) / steps
                let ya: Double = yStart + ((yEnd - yStart) * i) / steps
                let yb: Double = yStart + ((yEnd - yStart) * (i + 1.0)) / steps
                if isTop {
                    let ov: Double = Math.max(-ya, -yb)
                    if ov > 0 {
                        try self.insertSkylineTop(xa, xb, ov)
                    }
                } else {
                    let ov: Double = Math.max(ya, yb) - rendererBottom
                    if ov > 0 {
                        try self.insertSkylineBottom(xa, xb, ov)
                    }
                }
                i += 1
            }
        }
    }

    internal func initializeBeamDrawingInfo(_ h: BeamingHelper, _ direction: BeamDirection) throws -> BeamingHelperDrawInfo {
        let drawingInfo: BeamingHelperDrawInfo = h.getDrawingInfo(direction)
        let firstBeat: Beat = h.beats[0]
        let lastBeat: Beat = h.beats[(h.beats.length - 1.0).toInt()]
        drawingInfo.startBeat = firstBeat
        drawingInfo.startX = self.getBeatX(firstBeat, BeatXPosition.Stem)
        try drawingInfo.startY = direction == BeamDirection.Up ? self.getFlagTopY(firstBeat, direction) : self.getFlagBottomY(firstBeat, direction)
        drawingInfo.endBeat = lastBeat
        drawingInfo.endX = self.getBeatX(lastBeat, BeatXPosition.Stem)
        try drawingInfo.endY = direction == BeamDirection.Up ? self.getFlagTopY(lastBeat, direction) : self.getFlagBottomY(lastBeat, direction)
        let maxSlope: Double = self.smuflMetrics.oneStaffSpace
        if direction == BeamDirection.Down && drawingInfo.startY > drawingInfo.endY && drawingInfo.startY - drawingInfo.endY > maxSlope {
            drawingInfo.endY = drawingInfo.startY - maxSlope
        }
        if direction == BeamDirection.Down && drawingInfo.endY > drawingInfo.startY && drawingInfo.endY - drawingInfo.startY > maxSlope {
            drawingInfo.startY = drawingInfo.endY - maxSlope
        }
        if direction == BeamDirection.Up && drawingInfo.startY < drawingInfo.endY && drawingInfo.endY - drawingInfo.startY > maxSlope {
            drawingInfo.endY = drawingInfo.startY + maxSlope
        }
        if direction == BeamDirection.Up && drawingInfo.endY < drawingInfo.startY && drawingInfo.startY - drawingInfo.endY > maxSlope {
            drawingInfo.startY = drawingInfo.endY + maxSlope
        }
        return drawingInfo
    }

    internal var beamSpacing: Double {
        get {
            return self.smuflMetrics.beamSpacing
        }
    }

    internal var beamThickness: Double {
        get {
            return self.smuflMetrics.beamThickness
        }
    }

    internal func ensureBeamDrawingInfo(_ h: BeamingHelper, _ direction: BeamDirection) throws {
        if h.hasDrawingInfo(direction) {
            return
        }
        let drawingInfo: BeamingHelperDrawInfo = try self.initializeBeamDrawingInfo(h, direction)
        h.markDrawingInfoValid(direction)
        let barCount: Double = try ModelUtils.getIndex(h.shortestDuration) - 2.0
        let barDrawingShift: Double = self.applyBarShift(h, direction, drawingInfo, barCount)
        if h.beats.length > 1 {
            if direction == BeamDirection.Up {
                let yNeededForHighestNote: Double = try barDrawingShift + self.getFlagTopY(h.beatOfHighestNote, direction)
                let yGivenByCurrentValues: Double = drawingInfo.calcY(self.getBeatX(h.beatOfHighestNote, BeatXPosition.Stem))
                let diff: Double = yGivenByCurrentValues - yNeededForHighestNote
                if diff > 0 {
                    drawingInfo.startY -= diff
                    drawingInfo.endY -= diff
                }
            } else {
                let yNeededForLowestNote: Double = try barDrawingShift + self.getFlagBottomY(h.beatOfLowestNote, direction)
                let yGivenByCurrentValues: Double = drawingInfo.calcY(self.getBeatX(h.beatOfLowestNote, BeatXPosition.Stem))
                let diff: Double = yNeededForLowestNote - yGivenByCurrentValues
                if diff > 0 {
                    drawingInfo.startY += diff
                    drawingInfo.endY += diff
                }
            }
            var barSpacing: Double = 0.0
            if h.restBeats.length > 0 {
                let scaleMod: Double = h.graceType != GraceType.None ? EngravingSettings.GraceScale : 1.0
                barSpacing = barCount * (self.beamSpacing + self.beamThickness) * scaleMod
            }
            for b in h.restBeats {
                if try b.isRest && b.index < h.beats.jsElement((h.beats.length - 1.0).toInt()).index {
                    if direction == BeamDirection.Up {
                        let yNeededForRest: Double = try jsNonNull(self.getBeatContainer(b)).getBoundingBoxTop() - barSpacing
                        let yGivenByCurrentValues: Double = drawingInfo.calcY(self.getBeatX(b, BeatXPosition.Stem))
                        let diff: Double = yGivenByCurrentValues - yNeededForRest
                        if diff > 0 {
                            drawingInfo.startY -= diff
                            drawingInfo.endY -= diff
                        }
                    } else if (direction as! BeamDirection) == BeamDirection.Down {
                        let yNeededForRest: Double = try jsNonNull(self.getBeatContainer(b)).getBoundingBoxBottom() + barSpacing
                        let yGivenByCurrentValues: Double = drawingInfo.calcY(self.getBeatX(b, BeatXPosition.Stem))
                        let diff: Double = yNeededForRest - yGivenByCurrentValues
                        if diff > 0 {
                            drawingInfo.startY += diff
                            drawingInfo.endY += diff
                        }
                    }
                }
            }
            if h.slashBeats.length > 0 {
                for b in h.slashBeats {
                    let yGivenByCurrentValues: Double = drawingInfo.calcY(self.getBeatX(b, BeatXPosition.Stem))
                    let yNeededForSlash: Double = try direction == BeamDirection.Up ? self.getFlagTopY(b, direction) : self.getFlagBottomY(b, direction)
                    let diff: Double = yNeededForSlash - yGivenByCurrentValues
                    if diff > 0 {
                        drawingInfo.startY += diff
                        drawingInfo.endY += diff
                    }
                }
            }
        }
        if direction == BeamDirection.Up {
            drawingInfo.startY = Math.round(drawingInfo.startY)
            drawingInfo.endY = Math.round(drawingInfo.endY)
        } else {
            drawingInfo.startY = Math.round(drawingInfo.startY)
            drawingInfo.endY = Math.round(drawingInfo.endY)
        }
    }

    internal func applyBarShift(_ h: BeamingHelper, _ direction: BeamDirection, _ drawingInfo: BeamingHelperDrawInfo, _ barCount: Double) -> Double {
        var barDrawingShift: Double = 0.0
        let isRest: Bool = h.isRestBeamHelper
        let scale: Double = h.graceType != GraceType.None ? EngravingSettings.GraceScale : 1.0
        if barCount > 2 && !isRest {
            let beamSpacing: Double = self.beamSpacing * scale
            let beamThickness: Double = self.beamThickness * scale
            let totalBarsHeight: Double = barCount * beamThickness + (barCount - 1.0) * beamSpacing
            if direction == BeamDirection.Up {
                let bottomBarY: Double = drawingInfo.startY + 2.0 * beamThickness + beamSpacing
                let barTopY: Double = bottomBarY - totalBarsHeight
                let diff: Double = drawingInfo.startY - barTopY
                if diff > 0 {
                    barDrawingShift = diff * -1.0
                    drawingInfo.startY -= diff
                    drawingInfo.endY -= diff
                }
            } else {
                let topBarY: Double = drawingInfo.startY - 2.0 * beamThickness + beamSpacing
                let barBottomY: Double = topBarY + totalBarsHeight
                let diff: Double = barBottomY - drawingInfo.startY
                if diff > 0 {
                    barDrawingShift = diff
                    drawingInfo.startY += diff
                    drawingInfo.endY += diff
                }
            }
        }
        return barDrawingShift
    }

    internal func getMinLineOfBeat(_ _beat: Beat) throws -> Double {
        return 0.0
    }

    internal func getMaxLineOfBeat(_ _beat: Beat) throws -> Double {
        return 0.0
    }

    open func getNoteLine(_ note: Note) throws -> Double {
        fatalError("abstract")
    }

    public override init(_ renderer: ScoreRenderer, _ bar: Bar) {
        super.init(renderer, bar)
    }
}

/**
 * Vertical envelope of a 's beam/flag/tuplet-bracket
 * extent, shared by the scalar overflow pass and the per-x skyline pass.
 */
internal final class BeamingBounds: IRecord {
    public var topY: Double = 0.0

    public var bottomY: Double = 0.0

    public init(topY: Double, bottomY: Double) {
        self.topY = topY
        self.bottomY = bottomY
    }
}
